// Native transcription of the owner-supplied early historical Paper 2 pages.
// Printed prompts, figures, forms and marks are retained; no solutions appear here.
const p = (text) => ({ type: "paragraph", text });
const t = (caption, columns, rows) => ({ type: "table", caption, columns, rows });
const part = (label, text, marks) => ({ type: "part", label, text, marks });
const form = (answerId, caption, columns, rows, options = {}) => ({
  ...t(caption, columns, rows), answerSpace: true, answerId,
  readOnlyCells: rows.flatMap((row, r) => row.flatMap((cell, c) => cell === "" && !options.editableCells?.includes(`${r}:${c}`) ? [`${r}:${c}`] : [])),
  ...options,
});

